format_data:
[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "<div class="print-heading">				<h2><div>Purchase Order</div><br><small class="sub-heading">{{ _(doc.name) }}</small>				</h2></div>"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<style>
    [document-status] {
        display: none;
    }

    .print-heading {
        display: none;
    }
</style>

<div style="width: 100%;float: left;">
    <p style="font-size: 13px;color: black;font-weight: 600;text-align: center;">SERVICE ORDER</p>
</div>

<div style="width: 100%;float: left;">
    <p style="font-size: 13px;color: black;font-weight: 600;text-align: left;">
        Service Order No : {{doc.name}}
    </p>
</div>

<div style="width: 100%;float: left;border: 1px solid black;">
    <div style="width: 50%;float: left;padding: 0 5px;height: 250px;">
        <p style="font-size: 13px;color: black;font-weight: 600;text-align: left;">TO(Vendor Name):</p>
        <p style="font-size: 13px;color: black;text-align: left;">
            {% if doc.supplier_name %} {{doc.supplier_name}} {% endif %} <br>
            {% if doc.supplier_address %}
                {% set supplier_address = frappe.get_doc('Address', doc.supplier_address) %}
                {% if supplier_address.address_line1 %} {{supplier_address.address_line1}}{% endif %}
                {% if supplier_address.address_line2 %} {{supplier_address.address_line2}}{% endif %}
                {% if supplier_address.city %} {{supplier_address.city}},{% endif %}
                {% if supplier_address.state %} {{supplier_address.state}},{% endif %}
                {% if supplier_address.pincode %} Pincode : {{supplier_address.pincode}} {% endif %}
            {% endif %}
        </p>
        <p style="font-size: 13px;color: black;font-weight: 600;text-align: left;">Contact Name : </p>
        <p style="font-size: 13px;color: black;text-align: left;">
            {% if doc.contact_display %} {{doc.contact_display}} {% endif %}
        </p>
        <p style="font-size: 13px;color: black;font-weight: 600;text-align: left;">Email Id : </p>
        <p style="font-size: 13px;color: black;text-align: left;">
            {% if doc.contact_email %} {{doc.contact_email}} {% endif %}
        </p>
        <p style="font-size: 13px;color: black;font-weight: 600;text-align: left;">GST Registration No : </p>
        <p style="font-size: 13px;color: black;text-align: left;">
            {% if doc.company_gstin %} {{doc.company_gstin}} {% endif %}
        </p>
    </div>

    <div style="width: 50%;float: left;padding: 0 5px;border-left: 1px solid black;height: 250px;">
        <p style="font-size: 13px;color: black;font-weight: 600;text-align: left;"> Bill To (Company):</p>
        <p style="font-size: 13px;color: black;font-weight: 600;text-align: left;"> {% if doc.company %} {{doc.company}} {% endif %}</p>
        <p style="font-size: 13px;color: black;text-align: left;">
            {% if doc.billing_address %}
                {% set billing_address = frappe.get_doc('Address', doc.billing_address) %}
                {% if billing_address.address_line1 %} {{billing_address.address_line1}}{% endif %}
                {% if billing_address.address_line2 %} {{billing_address.address_line2}}{% endif %}
                {% if billing_address.city %} {{billing_address.city}}, {% endif %}
                {% if billing_address.state %} {{billing_address.state}},{% endif %}
                {% if billing_address.pincode %} Pincode : {{billing_address.pincode}} {% endif %}
            {% endif %}
        </p>
        <p style="font-size: 13px;color: black;font-weight: 600;text-align: left;">Contact Name : </p>
        <p style="font-size: 13px;color: black;text-align: left;">
            {% if doc.contact_display %} {{doc.contact_display}} {% endif %}
        </p>
        <p style="font-size: 13px;color: black;font-weight: 600;text-align: left;">Email Id : </p>
        <p style="font-size: 13px;color: black;text-align: left;">
            {% if doc.contact_email %} {{doc.contact_email}} {% endif %}
        </p>
        <p style="font-size: 13px;color: black;font-weight: 600;text-align: left;">GST Registration No : </p>
        <p style="font-size: 13px;color: black;text-align: left;">
            {% if doc.company_gstin %} {{doc.company_gstin}} {% endif %}
        </p>
    </div>
</div>

<div style="width: 100%;float: left;border: 1px solid black;margin-top: 5px;padding: 0 5px;">
    <p style="font-size: 13px;color: black;text-align: left;"><b>Project Code:</b>{% if doc.project_code %} {{doc.project_code}} {% endif %}</p>
    <p style="font-size: 13px;color: black;text-align: left;"><b>Service Order Date:</b> {% if doc.custom_service_order_from %} {{doc.get_formatted('custom_service_order_from')}} {% endif %}</p>
    <p style="font-size: 13px;color: black;text-align: left;"><b>Loading Plant:</b> {% if doc.loading_plant %} {{doc.loading_plant}} {% endif %}</p>
    <p style="font-size: 13px;color: black;text-align: left;"><b>Unloading Site:</b> {% if doc.custom_unloading_plant %} {{doc.custom_unloading_plant}} {% endif %}</p>
    <p style="font-size: 13px;color: black;text-align: left;"><b>Lead Distance:</b>{% if doc.custom_lead_distance %} {{doc.custom_lead_distance}} {% endif %}</p>
</div>

<div style="width: 100%;float: left;border: 1px solid black;margin-top: 5px;padding: 0 5px;">
    <p style="font-size: 13px;color: black;text-align: left;"><b>Work Order Effective From:</b>{% if doc.custom_work_order_effective_from %} {{doc.get_formatted('custom_work_order_effective_from')}} {% endif %}</p>
    <p style="font-size: 13px;color: black;text-align: left;"><b>Service Completion Date:</b>{% if doc.custom_service_completion_date %} {{doc.get_formatted('custom_service_completion_date')}} {% endif %}</p>
    <p style="font-size: 13px;color: black;text-align: left;"><b>Period:</b>{% if doc.custom_service_period_from %} {{doc.get_formatted('custom_service_period_from')}} {% endif %} {% if doc.custom_service_period_to %} {{doc.get_formatted('custom_service_period_to')}} {% endif %}</p>
    <p style="font-size: 13px;color: black;text-align: left;"><b>Billing Cycle:</b>{% if doc.billing_cycle %} {{doc.billing_cycle}} {% endif %}</p>
    <p style="font-size: 13px;color: black;text-align: left;"><b>Other Ref:</b>{% if doc.custom_other_ref %} {{doc.custom_other_ref}} {% endif %}</p>
</div>


<div style="width: 100%;float: left;margin-top: 5px;">
    <p style="font-size: 13px;color: black;text-align: left;font-weight: 600;">PRICE SCHEDULE</p>
</div>

{% set tax_rate = {"igst":0.0, "cgst":0.0,"sgst":0.0} %}

{% for row in doc.taxes %}
    
    {% if row.gst_tax_type == 'igst' and row.rate !=0 %}
        {% set _ = tax_rate.update({"igst":row.rate}) %}
    {% endif %}
    
    {% if row.gst_tax_type == 'sgst' and row.gst_tax_type == 'cgst' and row.rate !=0 %}
        {% set _ = tax_rate.update({"sgst":row.rate}) %}
        {% set _ = tax_rate.update({"cgst":row.rate}) %}
    {% endif %}

{% endfor %}


<div style="width: 100%;float: left;margin-top: 2px;">
    <table style="width: 100%;">
        <thead>
            <th style="font-size: 12px;color: black;font-weight: 600;text-align: center;border: 1px solid black;">SNO</th>
            <th style="font-size: 12px;color: black;font-weight: 600;text-align: center;border: 1px solid black;">Description of Work</th>
            <th style="font-size: 12px;color: black;font-weight: 600;text-align: center;border: 1px solid black;">UOM</th>
            <th style="font-size: 12px;color: black;font-weight: 600;text-align: center;border: 1px solid black;">HSN/SAC Code</th>
            <th style="font-size: 12px;color: black;font-weight: 600;text-align: center;border: 1px solid black;">Qty</th>
            <th style="font-size: 12px;color: black;font-weight: 600;text-align: center;border: 1px solid black;">Unit Rate</th>
            {% if tax_rate.igst != 0 %}
            <th style="font-size: 12px;color: black;font-weight: 600;text-align: center;border: 1px solid black;">IGST</th>
            {% endif %}

            {% if tax_rate.sgst!=0 and tax_rate.cgst!=0 %}
            <th style="font-size: 12px;color: black;font-weight: 600;text-align: center;border: 1px solid black;">CGST</th>
            <th style="font-size: 12px;color: black;font-weight: 600;text-align: center;border: 1px solid black;">SGST</th>
            {% endif %}
            <th style="font-size: 12px;color: black;font-weight: 600;text-align: center;border: 1px solid black;">Total</th>
        </thead>
        <tbody>
            {% for row in doc.items %}
            <tr>
                <td style="font-size: 12px;color: black;text-align: center;border: 1px solid black;">{{loop.index}}</td>
                <td style="font-size: 12px;color: black;text-align: left;border: 1px solid black;">{% if row.description %} {{row.description}} {% endif %}</td>
                <td style="font-size: 12px;color: black;text-align: center;border: 1px solid black;">{% if row.uom %} {{row.uom}} {% endif %}</td>
                <td style="font-size: 12px;color: black;text-align: center;border: 1px solid black;">{% if row.gst_hsn_code %} {{row.gst_hsn_code}} {% endif %}</td>
                <td style="font-size: 12px;color: black;text-align: center;border: 1px solid black;">{% if row.qty %} {{row.qty}} {% endif %}</td>
                <td style="font-size: 12px;color: black;text-align: right;border: 1px solid black;">{% if row.rate %} {{row.rate}} {% endif %}</td>
                
                {% if tax_rate.igst %}
                <td style="font-size: 12px;color: black;text-align: center;border: 1px solid black;">{{tax_rate.igst}}</td>
                {% endif %}
                {% if tax_rate.sgst and tax_rate.cgst %} 
                <td style="font-size: 12px;color: black;text-align: center;border: 1px solid black;">{{tax_rate.sgst}}</td>
                <td style="font-size: 12px;color: black;text-align: center;border: 1px solid black;">{{tax_rate.cgst}}</td>
                {% endif %}

                <td style="font-size: 12px;color: black;text-align: right;border: 1px solid black;">{% if row.amount %} {{row.amount}} {% endif %}</td>
            </tr>
            {% endfor %}
            <tr>
                <td style="font-size: 12px;color: black;font-weight: 600;text-align: left;border: 1px solid black;" colspan="7">Tax</td>
                <td style="font-size: 12px;color: black;font-weight: 600;text-align: right;border: 1px solid black;">
                    {% if doc.total_taxes_and_charges %} {{doc.total_taxes_and_charges}} {% endif %}
                </td>
            </tr>
            <tr>
                <td style="font-size: 12px;color: black;font-weight: 600;text-align: left;border: 1px solid black;" colspan="7">Sub Total</td>
                <td style="font-size: 12px;color: black;font-weight: 600;text-align: right;border: 1px solid black;">
                    {% if doc.total %} {{doc.total}} {% endif %}
                </td>
            </tr>
            <tr>
                <td style="font-size: 12px;color: black;font-weight: 600;text-align: left;border: 1px solid black;" colspan="7">Grand Total</td>
                <td style="font-size: 12px;color: black;font-weight: 600;text-align: right;border: 1px solid black;">
                    {% if doc.grand_total %} {{doc.grand_total}} {% endif %}
                </td>
            </tr>
        </tbody>
    </table>
</div>"}]
